def shortest_path(graph, start, end):
    # 无权图最短路径：BFS 逐层扩散 + 前驱还原（最少条件链跳数）
    if start == end:
        return [start]
    from collections import deque
    prev = {start: None}
    queue = deque([start])
    while queue:
        cur = queue.popleft()
        for nxt in graph.neighbors(cur):
            if nxt not in prev:
                prev[nxt] = cur
                if nxt == end:
                    path = []
                    node = nxt
                    while node is not None:
                        path.append(node)
                        node = prev[node]
                    return path[::-1]
                queue.append(nxt)
    return None

