def page_fault_handler(page_table, vpn, free_frames, load):
    # 缺页处理：present=0 → 分配空闲帧加载；无空闲帧 → 拒绝（置换由上层调度）
    if vpn in page_table and page_table[vpn].get('present') == 1:
