    chains = []
    def walk(cur, path):
        if len(path) > max_len:
            return
        succ = graph.neighbors(cur)
        if not succ:
            chains.append(list(path))
            return
        for nxt in succ:
            if nxt not in path:
                path.append(nxt)
                walk(nxt, path)
                path.pop()
    walk(condition, [condition])
    return sorted(chains)

