def pagerank(graph, iterations=5, damping=0.85):
    # PageRank：权重迭代传播（出链均分，阻尼因子防死端）
    nodes = sorted(graph.nodes)
    n = len(nodes)
    pr = {node: 1.0 / n for node in nodes}
    for _ in range(iterations):
        new_pr = {node: (1 - damping) / n for node in nodes}
        for node in nodes:
            out = graph.neighbors(node)
            if not out:
                continue
            share = damping * pr[node] / len(out)
            for nxt in out:
                new_pr[nxt] += share
        pr = new_pr
    return pr

