def bloom_filter(items, probe):
    # 布隆过滤器：多哈希位数组（成员可能判定，误报可接受）
    size = 64
    bits = [False] * size
    def h1(x):
        return sum(ord(c) for c in x) % size
    def h2(x):
        return (len(x) * 7 + sum(ord(c) for c in x)) % size
    for it in items:
        bits[h1(it)] = bits[h2(it)] = True
    return bits[h1(probe)] and bits[h2(probe)]

