def rwlock_op(lock, op):
    # 读写锁：多读并发/写独占（读者计数 + 写者标志）
    if op == 'r_lock':
        if lock.get('writer'):
            return 'blocked'
        lock['readers'] = lock.get('readers', 0) + 1
        return 'r_acquired'
    if op == 'w_lock':
        if lock.get('writer') or lock.get('readers', 0) > 0:
            return 'blocked'
        lock['writer'] = True
        return 'w_acquired'
    if op == 'r_unlock':
        lock['readers'] = max(0, lock.get('readers', 0) - 1)
        return 'r_released'
    if op == 'w_unlock':
        lock['writer'] = False
        return 'w_released'
    return None

